    /**
     * El SVG de un glifo conocido. Una clave que no está en el catálogo cae
     * en `enlace` (un eslabón genérico) y no en nada: un contacto con icono
     * roto se ve peor que uno con el icono más neutro que hay.
     */
    public static function svg(string $clave, string $clases = 'h-4 w-4 shrink-0'): string
    {
        [$viewBox, $d] = self::GLIFOS[$clave] ?? self::GLIFOS['enlace'];

        return sprintf(
            '<svg viewBox="%s" fill="currentColor" aria-hidden="true" class="%s"><path d="%s"/></svg>',
            Vista::e($viewBox),
            Vista::e($clases),
            Vista::e($d),
        );
    }

    /**
     * Deduce el glifo de una red social a partir de su nombre en el panel:
     * `redes` ya trae el nombre («LinkedIn», «Instagram»…) porque el pie lo
     * necesita para el texto del enlace, así que un campo `icono` aparte
     * solo repetiría ese dato y podría quedar desincronizado si alguien
     * cambia el nombre y olvida el icono — la misma razón por la que
     * `Cuestionario::definicion()` deduce la salida crítica de
     * `Catalogo::esCritico()` en vez de mantener una segunda lista (§4.2 de
     * CLAUDE.md).
     */
    public static function deRed(string $nombre): string
    {
        $clave = mb_strtolower(trim($nombre));
        $clave = str_replace(['á', 'é', 'í', 'ó', 'ú'], ['a', 'e', 'i', 'o', 'u'], $clave);

        return match (true) {
            str_contains($clave, 'facebook') => 'facebook',
            str_contains($clave, 'instagram') => 'instagram',
            str_contains($clave, 'linkedin') => 'linkedin',
            str_contains($clave, 'tiktok') => 'tiktok',
            str_contains($clave, 'youtube') => 'youtube',
            str_contains($clave, 'whatsapp') => 'whatsapp',
            $clave === 'x' || str_contains($clave, 'twitter') => 'x',
            default => 'enlace',
        };
    }
}
